// Shared frame for every Cloudy Bay page. One place defines the topics: the top bar's nav, the
// landing page's topic grid, the links under each topic's results, and the small list pages
// (required farms, suggested squads) all render from TOPICS / LISTS below.
(function(){
  // Each topic's page (daily.html, tb.html, ...) is generated by the publish run and opens on the
  // latest results; `pages` are the links shown under them.
  const TOPICS = [
    { id:'daily', href:'daily.html', label:'Daily', title:'Daily activity',
      lede:'Raid tickets and who’s been around.',
      pages:[] },
    { id:'tb', href:'tb.html', label:'TB', title:'Territory Battle',
      lede:'Rise of the Empire — results, platoons and what we need to farm for more stars.',
      pages:[
        { href:'rote-platoons.html', title:'Platoons', desc:'Platoon fill by planet, assignments, and who’s closest' },
        { href:'tb-required.html', title:'Missing toons for platoons', desc:'Toons we can’t place yet — and who’s closest to them' },
        { href:'tb-farms.html', title:'Required farms', desc:'Special-mission teams the guild needs' },
      ]},
    { id:'tw', href:'tw.html', label:'TW', title:'Territory War',
      lede:'Our war record — results, opponents and margins.',
      pages:[
        { href:'tw-map.html', title:'Map', desc:'Where each team goes on defense' },
        { href:'tw-farms.html', title:'Required farms', desc:'Teams the guild needs for war' },
      ]},
    { id:'raid', href:'raid.html', label:'Raid', title:'Raids',
      lede:'Guild raid results with every member’s score and trend.',
      pages:[
        { href:'raid-squads.html', title:'Suggested squads', desc:'Teams that score well in the current raid' },
      ]},
    { id:'members', href:'members.html', label:'Members', title:'Members',
      lede:'Every member’s roster, plus tools to plan your own farming.',
      pages:[
        { href:'player.html', title:'Players data', desc:'Roster, gear and relics, GP, journeys, mods — and the gear planner' },
        { title:'Roster changes', desc:'Who joined, who left, and returning members', soon:true },
      ]},
  ];

  // Small list pages: a page with <body data-list="key">. Empty lists say so.
  const LISTS = {
    'tb-farms': { topic:'tb', title:'Required farms', lede:'Teams the guild needs for Territory Battle special missions. Farm these first.',
      items:[
        { href:'reva-readiness.html', title:'Reva', desc:'Inquisitor team for the Reva special mission — any 5 of 7 at R7' },
      ]},
    'tw-farms': { topic:'tw', title:'Required farms', lede:'Teams the guild needs for Territory War.', items:[] },
    'raid-squads': { topic:'raid', title:'Suggested squads', lede:'Teams that score well in the current raid.', items:[] },
  };

  // Which topic a sub-page belongs to.
  const PARENT = { 'rote-platoons.html':'tb', 'tb-required.html':'tb', 'reva-readiness.html':'tb', 'tw-map.html':'tw','player.html':'members' };

  const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const file = (location.pathname.split('/').pop() || 'index.html').toLowerCase();
  function topicOf(){
    const b = document.body.dataset;
    if (b.topic) return b.topic;
    if (b.list && LISTS[b.list]) return LISTS[b.list].topic;
    const hub = TOPICS.find(t => t.href === file);
    return hub ? hub.id : PARENT[file] || null;
  }

  // Site meta (last updated + guild numbers) — fetched fresh, shared with the landing page.
  const meta = fetch('site-meta.json?_=' + Date.now(), { cache:'no-store' })
    .then(r => r.ok ? r.json() : null).catch(() => null);

  function ago(iso){
    const h = (Date.now() - new Date(iso)) / 3600000;
    if (h < 1) return 'just now';
    if (h < 24) return Math.round(h) + 'h ago';
    return Math.round(h / 24) + 'd ago';
  }

  function cardHtml(p){
    const tag = p.tag ? `<em class="cb-tag">${esc(p.tag)}</em>` : p.soon ? '<em class="cb-tag">Soon</em>' : '';
    const body = `<b>${esc(p.title)}${tag}</b><span>${esc(p.desc)}</span>`;
    return p.soon || !p.href ? `<li><div class="cb-card soon">${body}</div></li>`
                             : `<li><a class="cb-card" href="${esc(p.href)}">${body}</a></li>`;
  }
  window.CB = { TOPICS, meta, esc, cardHtml };

  function renderBar(){
    const bar = document.createElement('header');
    bar.className = 'cb-bar';
    bar.innerHTML =
      `<a class="cb-brand" href="index.html">Cloudy Bay</a>` +
      `<nav class="cb-nav">${TOPICS.map(t => `<a href="${t.href}" data-topic="${t.id}">${esc(t.label)}</a>`).join('')}</nav>` +
      `<div class="cb-tools"><span class="cb-upd"></span>` +
      `<label title="Some members share a name — the ally code tells them apart"><input type="checkbox" class="cb-ally"> Ally codes</label></div>`;
    document.body.prepend(bar);
    if (parseFloat(getComputedStyle(document.body).paddingLeft) < 8) bar.classList.add('cb-pad');

    const cur = topicOf();
    bar.querySelectorAll('.cb-nav a').forEach(a => a.classList.toggle('on', a.dataset.topic === cur));

    // Ally-code reveal: one site-wide switch, remembered per browser. Pages pre-render codes as
    // hidden .ally spans; the body class shows them.
    const tog = bar.querySelector('.cb-ally');
    let on = false; try { on = localStorage.getItem('cb-show-ally') === '1'; } catch {}
    tog.checked = on; document.body.classList.toggle('show-ally', on);
    tog.onchange = () => {
      document.body.classList.toggle('show-ally', tog.checked);
      try { localStorage.setItem('cb-show-ally', tog.checked ? '1' : '0'); } catch {}
    };

    meta.then(m => {
      if (!m || !m.updated) return;
      const el = bar.querySelector('.cb-upd');
      el.textContent = 'Updated ' + ago(m.updated);
      el.title = new Date(m.updated).toLocaleString();
      // Publishing runs every few hours; flag it if a run seems to have been missed.
      if ((Date.now() - new Date(m.updated)) / 3600000 > 12) el.classList.add('stale');
    });
  }

  // Sub-page links: a small nav row next to the page title, on every page of a topic — the topic's
  // results page first, then its pages. Styled like the top bar; the current page is underlined.
  const SUB_PARENT = { 'reva-readiness.html':'tb-farms.html' };   // pages reached through a list page
  function renderSubNav(){
    const t = TOPICS.find(x => x.id === topicOf()); if (!t) return;
    const items = [{ href:t.href, title: t.id === 'members' ? 'Overview' : 'Results' }, ...t.pages.filter(p => p.href && !p.soon)];
    if (items.length < 2) return;
    const h1 = [...document.querySelectorAll('h1')].find(h => !h.closest('.cb-bar')); if (!h1) return;
    if (h1.parentElement.classList.contains('cb-titlerow')) return;   // already done
    const cur = SUB_PARENT[file] || file;
    const row = document.createElement('div');
    row.className = 'cb-titlerow';
    h1.replaceWith(row);
    row.append(h1);
    row.insertAdjacentHTML('beforeend', `<nav class="cb-sub">${items.map(p =>
      `<a href="${esc(p.href)}"${p.href.toLowerCase() === cur ? ' class="on"' : ''}>${esc(p.title)}</a>`).join('')}</nav>`);
  }

  // A static topic hub (members.html: <body data-topic> with a <main>) lists its pages as cards.
  function renderTopicLinks(){
    const t = TOPICS.find(x => x.id === document.body.dataset.topic); if (!t) return;
    if (document.getElementById('cb-links')) return;   // generated results page: links are in the sub-nav
    const main = document.querySelector('main') || document.body;
    main.classList.add('cb-hub');
    main.insertAdjacentHTML('beforeend',
      `<h1>${esc(t.title)}</h1><p class="cb-lede">${esc(t.lede)}</p><ul class="cb-cards">${t.pages.map(cardHtml).join('')}</ul>`);
    document.title = t.title + ' — Cloudy Bay';
  }

  function renderList(key){
    const l = LISTS[key]; if (!l) return;
    const main = document.querySelector('main') || document.body;
    main.classList.add('cb-hub');
    main.insertAdjacentHTML('beforeend',
      `<h1>${esc(l.title)}</h1><p class="cb-lede">${esc(l.lede)}</p>` +
      (l.items.length ? `<ul class="cb-cards">${l.items.map(cardHtml).join('')}</ul>`
                      : `<p class="cb-empty">Nothing here yet.</p>`));
    document.title = l.title + ' — Cloudy Bay';
  }

  function init(){
    renderBar();
    if (document.body.dataset.topic) renderTopicLinks();
    if (document.body.dataset.list) renderList(document.body.dataset.list);
    renderSubNav();
    // Some pages draw (and redraw) their title after loading data, e.g. the Players page switching
    // between the directory and a member — re-attach the sub-links whenever a new title appears.
    let queued = false;
    new MutationObserver(() => {
      if (queued) return; queued = true;
      queueMicrotask(() => { queued = false; renderSubNav(); });
    }).observe(document.body, { childList:true, subtree:true });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
